d(r) as (select jsonb_array_elements($json$[{"k":"vgn-a-breakfast","f":"vegan","d":"A","m":"breakfast","n":"Tofu scramble on toast","ds":"Golden, savoury scrambled tofu with spinach and tomatoes. Tastes like scrambled eggs.","pr":5,"ck":8,"st":["Drain the tofu and pat it dry with paper towel.","Heat the oil in a non-stick frying pan over medium heat. Crumble the tofu into the pan with your fingers into small, uneven pieces.","Sprinkle in the turmeric, garlic powder, salt and pepper and stir so the tofu turns yellow. Cook for 4 minutes, stirring, until heated through and starting to brown.","Halve the cherry tomatoes and add them with the spinach. Stir for 2 minutes until the spinach wilts.","Add the soy milk and stir for 30 seconds. This makes it creamy, like scrambled eggs.","Toast the bread and pile the scramble on top."],"tp":"A pinch of black salt (kala namak) from an Indian grocer gives it a real egg flavour.","dt":["vegan","vegetarian"],"c":524,"p":35.6,"cb":31.9,"ft":25.3,"ps":48,"i":[["Firm tofu",117,200,"2/3 block",null,null],["Wholegrain bread",96,70,"2 slices",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Soy milk",118,20,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Ground turmeric",119,0.5,"1/4 tsp",null,null],["Garlic powder",11,0.5,"a pinch",null,null]]},{"k":"vgn-a-lunch","f":"vegan","d":"A","m":"lunch","n":"Chickpea, quinoa and roast veg bowl with tahini","ds":"Roasted chickpeas and vegetables on quinoa with a lemony tahini dressing.","pr":10,"ck":25,"st":["Heat the oven to 200°C (180°C fan) and line a tray with baking paper.","Drain and rinse the chickpeas and pat them dry with paper towel. Peel the pumpkin and cut it into 2 cm cubes. Cut the broccoli into small florets. Thaw the edamame in a bowl of hot water for 2 minutes and drain.","Toss the chickpeas and pumpkin with the oil, paprika and a pinch of salt on the tray. Roast for 15 minutes, add the broccoli, and roast for 10 minutes more.","Meanwhile rinse the quinoa and simmer it in 100 ml of water, covered, for 12 minutes. Leave covered off the heat for 5 minutes and fluff with a fork.","Whisk the tahini with the lemon juice and 1 to 2 tablespoons of water until smooth and pourable. It will look thick and lumpy at first, keep whisking.","Put the spinach and quinoa in a bowl, top with the roast vegetables, chickpeas and edamame, and drizzle with the tahini dressing."],"tp":"Roast a double batch of chickpeas. They make a crunchy snack on their own.","dt":["vegan","vegetarian"],"c":635,"p":30.9,"cb":58.5,"ft":24.8,"ps":49,"i":[["Canned chickpeas, drained",104,120,"2/3 cup",null,null],["Quinoa, uncooked",93,50,"1/4 cup",null,null],["Pumpkin",51,120,"1 wedge",null,null],["Broccoli",8,80,"1 cup of small florets",null,null],["Frozen shelled edamame",113,60,"1/3 cup",null,null],["Baby spinach",27,30,"1 handful",null,null],["Tahini",120,15,"1 tbsp",null,null],["Lemon juice",36,15,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"vgn-a-dinner","f":"vegan","d":"A","m":"dinner","n":"Tofu satay stir-fry with noodles","ds":"Crispy tofu and crunchy vegetables in a peanut satay sauce over noodles.","pr":10,"ck":15,"st":["Put the noodles in a heatproof bowl and cover with boiling water. Leave for 5 to 8 minutes (check the packet) until soft, then drain and rinse with cold water so they do not stick.","Drain the tofu, press it between paper towels to squeeze out water, and cut it into 2 cm cubes.","Make the satay sauce: whisk the peanut butter, soy sauce, lime juice, grated garlic and ginger with 3 tablespoons of hot water until smooth.","Heat the oil in a wok or large frying pan over medium-high heat. Add the tofu and cook for 5 to 6 minutes, turning, until golden on most sides. Move it to a plate.","Add the broccoli, sliced capsicum and snow peas with 2 tablespoons of water. Stir-fry for 3 minutes until bright and just tender.","Add the noodles, tofu and satay sauce and toss for 1 minute until everything is coated and hot."],"tp":"Leave the tofu alone in the pan for the first 2 minutes. Moving it too early stops it going crispy.","dt":["vegan","vegetarian"],"c":713,"p":41.6,"cb":54,"ft":33.1,"ps":50,"i":[["Firm tofu",117,200,"2/3 block",null,null],["Rice stick noodles, soaked",121,170,"60 g dry, about 1 1/2 cups once soaked",null,null],["Broccoli",8,80,"1 cup of small florets",null,null],["Red capsicum",40,60,"1/2 small capsicum",null,null],["Snow peas",122,50,"1 handful",null,null],["Peanut butter, no added sugar",23,20,"1 heaped tbsp",null,null],["Salt-reduced soy sauce",10,15,"1 tbsp",null,null],["Lime juice",123,10,"juice of 1/2 lime",null,null],["Garlic",11,5,"1 clove",null,null],["Fresh ginger",106,5,"2 cm piece",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"vgn-a-snack","f":"vegan","d":"A","m":"snack","n":"Trail mix and soy milk","ds":"A handful of nuts, seeds and dried fruit with a glass of soy milk.","pr":2,"ck":0,"st":["Mix the almonds, pepitas and sultanas in a small container.","Pour a glass of cold soy milk.","Eat the trail mix with the milk."],"tp":"Choose a soy milk with added calcium to replace the calcium from dairy.","dt":["vegan","vegetarian"],"c":339,"p":15.7,"cb":24,"ft":19.3,"ps":51,"i":[["Almonds",124,15,"12 almonds",null,null],["Pepitas (pumpkin seeds)",114,10,"1 tbsp",null,null],["Sultanas",78,15,"1 tbsp",null,null],["Soy milk",118,250,"1 cup",null,null]]},{"k":"vgn-b-breakfast","f":"vegan","d":"B","m":"breakfast","n":"Berry chia overnight oats","ds":"Oats soaked in soy milk with chia seeds, plant protein and berries. Make the night before.","pr":5,"ck":0,"st":["Put the oats and chia seeds in a jar that holds about 500 ml.","Add the protein powder, then pour in the soy milk and maple syrup and stir very well until no powder lumps are left and the chia seeds are not clumped at the bottom.","Tip the frozen berries on top.","Put the lid on and refrigerate overnight, or for at least 4 hours. Give it a stir after the first 10 minutes if you can, to stop the chia clumping.","In the morning, stir and add the peanut butter on top."],"tp":"Keeps for 3 days in the fridge, so make several at once.","dt":["vegan","vegetarian"],"c":654,"p":40.2,"cb":61.5,"ft":23.6,"ps":52,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Soy milk",118,250,"1 cup",null,null],["Chia seeds",4,15,"1 tbsp",null,null],["Plant protein powder, unflavoured or vanilla",125,25,"1 scoop (about 1/4 cup)",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Peanut butter, no added sugar",23,10,"2 tsp",null,null],["Maple syrup",45,10,"2 tsp",null,null]]},{"k":"vgn-b-lunch","f":"vegan","d":"B","m":"lunch","n":"Red lentil and vegetable soup with bread","ds":"A thick, warming soup of red lentils, vegetables and spinach. Freezes well.","pr":10,"ck":25,"st":["Dice the onion, carrot and celery into small pieces. Chop the garlic.","Heat the oil in a saucepan over medium heat. Cook the onion, carrot and celery for 5 minutes until starting to soften.","Add the garlic and cumin and stir for 1 minute.","Rinse the lentils in a sieve. Add them to the pan with the tomatoes and 400 ml of water (or salt-reduced vegetable stock).","Bring to the boil, then simmer on low with the lid partly on for 18 to 20 minutes, stirring now and then, until the lentils are soft and breaking down.","Stir in the spinach until wilted. Season with salt and pepper. Add more water if you like it thinner.","Serve with the bread, toasted if you like."],"tp":"Make 4 serves at once and freeze the rest in single containers.","dt":["vegan","vegetarian"],"c":555,"p":30.1,"cb":73.9,"ft":9.3,"ps":53,"i":[["Red lentils, dry",126,90,"1/2 cup",null,null],["Carrot",9,60,"1/2 medium carrot",null,null],["Celery",112,40,"1 stick",null,null],["Brown onion",17,50,"1/2 small onion",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Baby spinach",27,30,"1 handful",null,null],["Garlic",11,5,"1 clove",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Wholegrain bread",96,50,"1 large slice",null,null]]},{"k":"vgn-b-dinner","f":"vegan","d":"B","m":"dinner","n":"Black bean and sweet potato tacos","ds":"Roasted sweet potato and spiced black beans in warm tortillas with avocado and crunchy slaw.","pr":15,"ck":25,"st":["Heat the oven to 200°C (180°C fan). Peel the sweet potato and cut it into 1.5 cm cubes. Toss with the oil, half the cumin and paprika, and salt on a lined tray. Roast for 20 to 25 minutes until soft and golden.","Rinse the black beans. Warm them in a small saucepan with the rest of the cumin and paprika and 2 tablespoons of water for 3 minutes, lightly mashing some with a fork.","Shred the cabbage thinly and toss with half the lime juice and a pinch of salt.","Mash the avocado with the rest of the lime juice and a pinch of salt.","Warm the tortillas one at a time in a dry frying pan for 20 seconds each side until soft.","Fill each tortilla with beans, sweet potato, slaw and avocado, and top with coriander."],"tp":"Wrap warmed tortillas in a clean tea towel to keep them soft while you build the tacos.","dt":["vegan","vegetarian"],"c":616,"p":20.9,"cb":86.3,"ft":14.9,"ps":54,"i":[["Corn tortillas",127,75,"3 small tortillas",null,null],["Canned black beans, drained",38,150,"3/4 cup",null,null],["Sweet potato",115,150,"1/2 medium sweet potato",null,null],["Avocado",31,40,"1/4 avocado",null,null],["Red cabbage",128,40,"1/2 cup shredded",null,null],["Lime juice",123,10,"juice of 1/2 lime",null,null],["Fresh coriander",129,3,"a few sprigs",null,null],["Olive oil",19,5,"1 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"vgn-b-snack","f":"vegan","d":"B","m":"snack","n":"Chilli salt edamame","ds":"Steamed edamame beans tossed with salt and chilli flakes.","pr":1,"ck":4,"st":["Put the frozen edamame in a microwave-safe bowl with 1 tablespoon of water.","Cover and microwave on high for 3 minutes, stirring halfway.","Drain and toss with a pinch of salt and chilli flakes."],"tp":"Edamame is one of the highest-protein plant snacks you can buy.","dt":["vegan","vegetarian"],"c":272,"p":23.3,"cb":10.7,"ft":12.9,"ps":55,"i":[["Frozen shelled edamame",113,200,"1 1/3 cups",null,null],["Chilli flakes",62,0.5,"a pinch",null,null]]},{"k":"vgn-c-breakfast","f":"vegan","d":"C","m":"breakfast","n":"Banana oat pancakes","ds":"Egg-free, dairy-free pancakes made from oats, banana and plant protein, with peanut butter and berries.","pr":10,"ck":10,"st":["Blend the oats in a blender for 20 seconds until they are like flour.","Add the banana, soy milk, protein powder, baking powder and a pinch of salt and blend until smooth. Leave the batter for 5 minutes to thicken.","Heat a non-stick pan over medium-low heat and spray lightly with oil.","Pour in about 3 tablespoons of batter per pancake. Cook for 2 to 3 minutes until bubbles appear and the edges look set, then flip carefully and cook for 1 to 2 minutes more.","Warm the berries in the microwave for 40 seconds.","Stack the pancakes, spread the peanut butter on top, add the berries and drizzle with maple syrup."],"tp":"These are softer than flour pancakes, so make them small and flip them gently.","dt":["vegan","vegetarian"],"c":627,"p":30.7,"cb":72.8,"ft":20.2,"ps":56,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Banana",24,100,"1 small banana",null,null],["Soy milk",118,120,"1/2 cup",null,null],["Plant protein powder, unflavoured or vanilla",125,20,"2/3 scoop",null,null],["Baking powder",130,3,"1/2 tsp",null,null],["Peanut butter, no added sugar",23,15,"1 tbsp",null,null],["Frozen mixed berries",3,50,"1/3 cup",null,null],["Maple syrup",45,10,"2 tsp",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"vgn-c-lunch","f":"vegan","d":"C","m":"lunch","n":"Smashed chickpea salad sandwich","ds":"A creamy, crunchy chickpea filling with avocado, celery and lemon on wholegrain bread.","pr":10,"ck":0,"st":["Rinse and drain the chickpeas well. Put them in a bowl and mash with a fork or potato masher until mostly broken up, with a few whole ones left for texture.","Add the avocado and mash it in. This replaces mayonnaise and makes it creamy.","Finely dice the celery and red onion and stir them in with the mustard, lemon juice, salt and plenty of pepper.","Slice the tomato.","Spread the chickpea mix thickly on one slice of bread, top with lettuce and tomato and close the sandwich."],"tp":"The filling keeps for 2 days in the fridge. Make the sandwich fresh so the bread does not go soggy.","dt":["vegan","vegetarian"],"c":451,"p":19.8,"cb":56.2,"ft":11.4,"ps":57,"i":[["Canned chickpeas, drained",104,150,"3/4 cup",null,null],["Wholegrain bread",96,80,"2 slices",null,null],["Avocado",31,30,"1/5 avocado",null,null],["Celery",112,30,"1/2 stick",null,null],["Red onion",73,15,"1 tbsp diced",null,null],["Dijon mustard",131,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Cos lettuce",32,20,"1 leaf",null,null],["Tomato",33,50,"1/2 small tomato",null,null]]},{"k":"vgn-c-dinner","f":"vegan","d":"C","m":"dinner","n":"Red lentil dahl with rice","ds":"A creamy, gently spiced lentil dahl with coconut, tomatoes and spinach. The ultimate comfort food.","pr":10,"ck":30,"st":["Rinse the rice and cook it in 100 ml of water: bring to the boil, cover, and cook on the lowest heat for 12 minutes. Leave covered off the heat.","Dice the onion, chop the garlic and grate the ginger.","Heat the oil in a saucepan over medium heat and cook the onion for 4 minutes until soft. Add the garlic, ginger, curry powder and turmeric and stir for 1 minute.","Rinse the lentils and add them with the tomatoes, coconut milk and 300 ml of water.","Bring to the boil, then simmer on low for 20 minutes, stirring often so the lentils do not stick, until thick and creamy. Add a splash of water if it gets too thick.","Stir in the spinach until wilted and season with salt.","Serve the dahl over the rice."],"tp":"A squeeze of lemon just before serving makes all the spices taste brighter.","dt":["vegan","vegetarian"],"c":627,"p":29.1,"cb":87.9,"ft":12.1,"ps":58,"i":[["Red lentils, dry",126,90,"1/2 cup",null,null],["Light coconut milk",105,60,"1/4 cup",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh ginger",106,5,"2 cm piece",null,null],["Baby spinach",27,50,"2 handfuls",null,null],["Basmati rice, uncooked",7,50,"1/4 cup",null,null],["Mild curry powder",107,3,"1 1/2 tsp",null,null],["Ground turmeric",119,1,"1/2 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"vgn-c-snack","f":"vegan","d":"C","m":"snack","n":"Chocolate peanut butter smoothie","ds":"A thick chocolate smoothie with soy milk, banana, peanut butter and plant protein.","pr":5,"ck":0,"st":["Put the soy milk, banana, protein powder, peanut butter, cocoa and ice in a blender.","Blend on high for 30 to 45 seconds until completely smooth.","Pour into a tall glass and drink straight away."],"tp":"Use a frozen banana instead of ice for a thicker, creamier smoothie.","dt":["vegan","vegetarian"],"c":470,"p":37.4,"cb":33.4,"ft":18.5,"ps":59,"i":[["Soy milk",118,300,"1 1/4 cups",null,null],["Banana",24,80,"2/3 banana",null,null],["Peanut butter, no added sugar",23,15,"1 tbsp",null,null],["Plant protein powder, unflavoured or vanilla",125,30,"1 scoop",null,null],["Cocoa powder",54,5,"1 tsp",null,null],["Ice cubes",55,50,"3 ice cubes",null,null]]},{"k":"pes-a-breakfast","f":"pescatarian","d":"A","m":"breakfast","n":"Smoked salmon and cream cheese bagel","ds":"A toasted bagel with light cream cheese, smoked salmon, capers and rocket.","pr":5,"ck":2,"st":["Slice the bagel in half and toast it.","Spread the cream cheese over both halves.","Lay the smoked salmon on top, then the onion rings, capers and rocket.","Squeeze over a little lemon juice and finish with black pepper."],"tp":"Keep opened smoked salmon in the fridge and use it within 2 days.","dt":["pescatarian"],"c":405,"p":26.1,"cb":44.5,"ft":12.7,"ps":60,"i":[["Bagel",132,85,"1 bagel",null,null],["Smoked salmon",133,60,"3 slices",null,null],["Light cream cheese",134,25,"1 1/2 tbsp",null,null],["Rocket",100,15,"1 small handful",null,null],["Red onion",73,10,"2 thin rings",null,null],["Capers",135,5,"1 tsp",null,null],["Lemon juice",36,5,"a squeeze",null,null]]},{"k":"pes-a-lunch","f":"pescatarian","d":"A","m":"lunch","n":"Prawn and avocado poke bowl","ds":"Garlic prawns on sushi-style rice with edamame, cucumber, carrot and avocado.","pr":15,"ck":15,"st":["Rinse the rice well and cook it in 130 ml of water: bring to the boil, cover and cook on the lowest heat for 12 minutes, then leave covered off the heat for 5 minutes. Stir in the rice vinegar and let it cool slightly.","Microwave the edamame with 1 tablespoon of water, covered, for 2 minutes. Drain.","Peel the carrot and grate it or cut it into thin matchsticks. Slice the cucumber and avocado.","Heat the sesame oil in a frying pan over medium-high heat. Add the prawns and chopped garlic and cook for 1 to 2 minutes each side until the prawns turn pink and curl into a C shape. Do not overcook or they go rubbery.","Put the rice in a bowl and arrange the prawns, edamame, cucumber, carrot and avocado on top in sections.","Drizzle with soy sauce and sprinkle with sesame seeds."],"tp":"Prawns are cooked when they are pink all over and curled into a C. A tight O shape means overcooked.","dt":["pescatarian"],"c":554,"p":40.5,"cb":57.2,"ft":15.4,"ps":61,"i":[["Raw peeled prawns",136,130,"8 to 10 prawns",null,null],["White rice, uncooked",7,65,"1/3 cup",null,null],["Frozen shelled edamame",113,50,"1/3 cup",null,null],["Cucumber",34,60,"1/2 cucumber",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Avocado",31,40,"1/4 avocado",null,null],["Salt-reduced soy sauce",10,15,"1 tbsp",null,null],["Rice vinegar",109,5,"1 tsp",null,null],["Sesame oil",12,3,"1/2 tsp",null,null],["Sesame seeds",13,3,"1 tsp",null,null],["Garlic",11,4,"1 clove",null,null]]},{"k":"pes-a-dinner","f":"pescatarian","d":"A","m":"dinner","n":"Honey soy salmon with rice and greens","ds":"Pan-fried salmon with a sticky honey soy glaze, brown rice and broccolini.","pr":5,"ck":25,"st":["Rinse the brown rice and simmer it in 140 ml of water, covered, for 25 minutes. Leave covered off the heat for 5 minutes.","Mix the soy sauce, honey, grated garlic and grated ginger in a cup.","Pat the salmon dry with paper towel. Heat a non-stick frying pan over medium-high heat. Put the salmon in skin side down and cook for 4 minutes without moving it, until the skin is crisp.","Flip the salmon and cook for 2 minutes. Pour the sauce around it and let it bubble for 1 to 2 minutes, spooning it over the fish, until sticky. The salmon is done when it flakes easily but is still slightly pink in the centre.","While the salmon cooks, steam or microwave the broccolini with 1 tablespoon of water for 2 to 3 minutes until bright green.","Serve the salmon on the rice with the broccolini, pour over the pan sauce and sprinkle with sesame seeds."],"tp":"Turn the heat down if the honey starts to burn. It catches quickly.","dt":["pescatarian"],"c":569,"p":39.4,"cb":48.5,"ft":22.7,"ps":62,"i":[["Salmon fillet, skin on",137,140,"1 fillet",null,null],["Brown rice, uncooked",37,55,"1/4 cup",null,null],["Broccolini",138,100,"1 bunch (about 8 stems)",null,null],["Salt-reduced soy sauce",10,15,"1 tbsp",null,null],["Honey",5,10,"1/2 tbsp",null,null],["Garlic",11,4,"1 clove",null,null],["Fresh ginger",106,4,"2 cm piece",null,null],["Sesame seeds",13,3,"1 tsp",null,null]]},{"k":"pes-a-snack","f":"pescatarian","d":"A","m":"snack","n":"Tuna and crackers with cherry tomatoes","ds":"Lemon pepper tuna piled on crackers with cherry tomatoes.","pr":3,"ck":0,"st":["Drain the tuna and mix it with the lemon juice and plenty of black pepper.","Halve the tomatoes.","Pile the tuna onto the crackers and eat with the tomatoes."],"tp":"Flavoured tuna tins are easy, but check the label: some are packed in oil and have twice the calories.","dt":["pescatarian"],"c":184,"p":21.1,"cb":14.7,"ft":3.4,"ps":63,"i":[["Tuna in springwater, drained",56,70,"1 small can",null,null],["Wholegrain crackers",64,20,"3 crackers",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Lemon juice",36,5,"a squeeze",null,null]]},{"k":"pes-b-breakfast","f":"pescatarian","d":"B","m":"breakfast","n":"Berry and banana protein porridge","ds":"Creamy porridge with Greek yoghurt stirred through for extra protein, topped with fruit.","pr":2,"ck":5,"st":["Put the oats and milk in a saucepan over medium heat. Cook for 4 to 5 minutes, stirring often, until thick and creamy. (Or microwave for 2 minutes, stir, then 1 minute more.)","Take it off the heat and stir in the yoghurt. Adding it off the heat keeps it creamy.","Warm the berries in the microwave for 40 seconds.","Spoon the porridge into a bowl and top with the berries and sliced banana."],"tp":"Stirring the yoghurt in at the end adds protein without making the porridge sour.","dt":["pescatarian"],"c":450,"p":21.1,"cb":63,"ft":9.7,"ps":64,"i":[["Rolled oats",0,55,"1/2 cup plus 1 tbsp",null,null],["Reduced fat milk",1,220,"1 cup",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Frozen mixed berries",3,60,"1/3 cup",null,null],["Banana",24,50,"1/2 small banana",null,null]]},{"k":"pes-b-lunch","f":"pescatarian","d":"B","m":"lunch","n":"Tuna, olive and feta pasta salad","ds":"Wholemeal pasta tossed with tuna, cherry tomatoes, olives, spinach and feta.","pr":10,"ck":12,"st":["Cook the pasta in boiling salted water for the time on the packet. Drain and rinse under cold water until cool.","Halve the tomatoes, dice the cucumber and slice the olives.","Whisk the olive oil and lemon juice with salt and pepper in a large bowl.","Add the pasta, tomatoes, cucumber, olives and spinach and toss through the dressing.","Drain the tuna, flake it over the top and crumble on the feta."],"tp":"Keeps for 2 days in the fridge. Add the spinach just before eating so it stays fresh.","dt":["pescatarian"],"c":501,"p":39.8,"cb":46.3,"ft":14.5,"ps":65,"i":[["Wholemeal pasta, dry",111,70,"3/4 cup",null,null],["Tuna in springwater, drained",56,95,"1 small can",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Baby spinach",27,30,"1 handful",null,null],["Kalamata olives",94,15,"4 olives",null,null],["Feta, reduced fat",86,15,"1 tbsp crumbled",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"pes-b-dinner","f":"pescatarian","d":"B","m":"dinner","n":"Crispy fish tacos with slaw","ds":"Spiced white fish in warm tortillas with crunchy slaw, avocado and a lime yoghurt sauce.","pr":15,"ck":10,"st":["Pat the fish dry with paper towel and cut it into 4 strips. Sprinkle both sides with the paprika, cumin, salt and pepper.","Shred the cabbage thinly and grate the carrot. Toss with half the lime juice and a pinch of salt.","Mix the yoghurt with the rest of the lime juice. This is your sauce.","Heat the oil in a non-stick frying pan over medium-high heat. Cook the fish for 2 to 3 minutes each side until golden and it flakes easily with a fork.","Warm the tortillas in a dry pan for 20 seconds each side.","Fill each tortilla with slaw, fish and sliced avocado, and drizzle with the lime yoghurt."],"tp":"Frozen white fish fillets are much cheaper than fresh and work perfectly here. Thaw in the fridge overnight.","dt":["pescatarian"],"c":485,"p":37.9,"cb":42.5,"ft":15.4,"ps":66,"i":[["White fish fillets (barramundi or basa)",139,150,"1 large fillet",null,null],["Corn tortillas",127,75,"3 small tortillas",null,null],["Red cabbage",128,50,"1/2 cup shredded",null,null],["Carrot",9,40,"1/2 small carrot",null,null],["Avocado",31,30,"1/5 avocado",null,null],["Greek yoghurt, low fat",2,40,"2 tbsp",null,null],["Lime juice",123,15,"juice of 1 lime",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"pes-b-snack","f":"pescatarian","d":"B","m":"snack","n":"Cottage cheese with pineapple","ds":"Creamy cottage cheese with sweet pineapple. A retro snack packed with protein.","pr":2,"ck":0,"st":["Spoon the cottage cheese into a bowl.","Drain the pineapple and add it on top.","Stir together, or eat as is."],"tp":"Fresh pineapple works too and is even better in summer.","dt":["pescatarian"],"c":159,"p":15,"cb":15.9,"ft":3,"ps":67,"i":[["Cottage cheese, reduced fat",108,120,"1/2 cup",null,null],["Pineapple pieces, drained",82,100,"1/2 cup",null,null]]},{"k":"pes-c-breakfast","f":"pescatarian","d":"C","m":"breakfast","n":"Smoked salmon scrambled eggs on sourdough","ds":"Soft scrambled eggs with smoked salmon and chives on buttered sourdough.","pr":5,"ck":6,"st":["Whisk the eggs with pepper (no salt, the salmon is salty). Chop the chives. Tear the salmon into strips.","Toast the sourdough.","Melt the butter in a non-stick pan over medium-low heat. Pour in the eggs and wait 20 seconds.","Slowly push the eggs from the edges into the middle with a spatula. Keep going until they are almost set but still glossy.","Take the pan off the heat and gently fold in the salmon and most of the chives.","Spoon onto the toast and sprinkle with the rest of the chives."],"tp":"Add the salmon off the heat. Cooking it makes it tough and very salty.","dt":["pescatarian"],"c":442,"p":34,"cb":26.3,"ft":21.7,"ps":68,"i":[["Eggs",26,150,"3 eggs","egg",50],["Smoked salmon",133,40,"2 slices",null,null],["Sourdough bread",85,60,"1 thick slice",null,null],["Butter",29,5,"1 tsp",null,null],["Fresh chives",140,3,"1 tbsp chopped",null,null]]},{"k":"pes-c-lunch","f":"pescatarian","d":"C","m":"lunch","n":"Salmon and potato fishcakes with salad","ds":"Golden fishcakes made with tinned salmon and potato, with a lemony salad.","pr":20,"ck":20,"st":["Peel the potato and cut it into chunks. Boil in salted water for 12 to 15 minutes until soft. Drain well and mash with a fork. Let it cool for 5 minutes.","Drain the salmon and flake it, removing any large bones and skin (the small soft bones are fine to eat and full of calcium).","Mix the salmon into the potato with the finely sliced spring onion, the beaten egg, half the lemon juice, salt and pepper.","Shape into 3 patties about 2 cm thick and press each side into the breadcrumbs.","Heat 1 teaspoon of the oil in a non-stick pan over medium heat. Cook the fishcakes for 3 to 4 minutes each side until golden and hot in the middle.","Toss the salad leaves and halved tomatoes with the rest of the oil and lemon juice and serve with the fishcakes."],"tp":"Chill the shaped fishcakes for 15 minutes before cooking and they hold together better.","dt":["pescatarian"],"c":408,"p":31.3,"cb":30.8,"ft":16.3,"ps":69,"i":[["Canned pink salmon, drained",141,105,"1 small can",null,null],["Potato",50,150,"1 medium potato",null,null],["Egg",26,25,"1/2 egg",null,null],["Spring onion",59,10,"1 stem",null,null],["Dry breadcrumbs",142,15,"2 tbsp",null,null],["Mixed salad leaves",47,40,"1 large handful",null,null],["Cherry tomatoes",28,60,"5 tomatoes",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"pes-c-dinner","f":"pescatarian","d":"C","m":"dinner","n":"Baked barramundi with lemon potatoes and greens","ds":"Lemon and garlic baked barramundi with crispy potatoes and green beans. An easy Sunday roast.","pr":10,"ck":40,"st":["Heat the oven to 210°C (190°C fan) and line a tray with baking paper.","Scrub the potato and cut it into 2 cm cubes. Toss with half the oil, salt and pepper on the tray. Roast for 25 minutes, turning once.","Rub the fish with the rest of the oil, the crushed garlic, half the lemon juice, salt and pepper.","Push the potatoes to the side, put the fish and green beans on the tray, and roast for 12 to 15 minutes until the fish is white all the way through and flakes easily.","Squeeze over the rest of the lemon juice and scatter with chopped parsley."],"tp":"Check the fish at 12 minutes. Thinner fillets cook faster.","dt":["pescatarian"],"c":382,"p":39.5,"cb":27.1,"ft":10.8,"ps":70,"i":[["Barramundi fillet",139,170,"1 large fillet",null,null],["Potato",72,200,"1 large potato",null,null],["Green beans",52,100,"1 large handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Lemon",36,15,"juice of 1/2 lemon",null,null],["Garlic",11,6,"2 cloves",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null]]},{"k":"pes-c-snack","f":"pescatarian","d":"C","m":"snack","n":"Mango lassi smoothie","ds":"A creamy mango, yoghurt and milk smoothie.","pr":5,"ck":0,"st":["Put the mango, yoghurt, milk and a pinch of cardamom or cinnamon in a blender.","Blend on high for 30 seconds until smooth and frothy.","Pour into a glass and drink cold."],"tp":"Frozen mango cubes make it thick and icy without needing ice.","dt":["pescatarian"],"c":210,"p":12.8,"cb":28.2,"ft":3.9,"ps":71,"i":[["Mango, fresh or frozen",143,100,"1/2 mango",null,null],["Greek yoghurt, low fat",2,100,"1/3 cup",null,null],["Reduced fat milk",1,150,"2/3 cup",null,null],["Cardamom or cinnamon",25,0.5,"a pinch",null,null]]}]$json$::jsonb)),
ins as (
  insert into public.recipes (id, slug, family, day_type, meal_type, name, description, prep_minutes, cook_minutes, steps, tip, diets, calories, protein_g, carbs_g, fats_g, position)
  select md5('unfnshd-meal-library:' || (r->>'k'))::uuid, r->>'k', r->>'f', r->>'d', r->>'m', r->>'n', r->>'ds', (r->>'pr')::int, (r->>'ck')::int, r->'st', r->>'tp',
    array(select jsonb_array_elements_text(r->'dt')), (r->>'c')::int, (r->>'p')::numeric, (r->>'cb')::numeric, (r->>'ft')::numeric, (r->>'ps')::int
  from d on conflict (id) do nothing
  returning id
)
insert into public.recipe_ingredients (id, recipe_id, position, label, food_id, grams, measure, each_label, each_grams, calories, protein_g, carbs_g, fats_g)
select md5('unfnshd-meal-library:' || ((r->>'k') || ':ing:' || (x.ord - 1)))::uuid, md5('unfnshd-meal-library:' || (r->>'k'))::uuid, x.ord - 1, x.e->>0, fd.id, (x.e->>2)::numeric, x.e->>3, x.e->>4, (x.e->>5)::numeric,
  round(fd.calories * (x.e->>2)::numeric / 100, 1), round(fd.protein_g * (x.e->>2)::numeric / 100, 1), round(fd.carbs_g * (x.e->>2)::numeric / 100, 1), round(fd.fats_g * (x.e->>2)::numeric / 100, 1)
from d cross join lateral jsonb_array_elements(r->'i') with ordinality as x(e, ord)
cross join f
join public.foods fd on fd.id = ((f.ids)->>((x.e->>1)::int))::uuid
on conflict (id) do nothing;
